class Solution:
    def invertTree(self, root: Optional[TreeNode]) -> Optional[TreeNode]:
        if root is None:
            return None
        stack = [root]
        while stack:
            node = stack.pop()
            node.left, node.right = node.right, node.left
            if node.left is not None:
                stack.append(node.left)
            if node.right is not None:
                stack.append(node.right)
        return root

class Solution:
    def climbStairs(self, n: int) -> int:
        # DP iterative approach to avoid recursion overhead and TLE
        if n <= 2:
            return n

        first, second = 1, 2
        for _ in range(3, n + 1):
            third = first + second
            first = second
            second = third

        return second

class Solution:
    def rob(self, nums: List[int]) -> int:
        # DP approach handling all edge cases
        if not nums:
            return 0
        if len(nums) == 1:
            return nums[0]

        n = len(nums)
        dp = [0] * n
        dp[0] = nums[0]
        dp[1] = max(nums[0], nums[1])

        for i in range(2, n):
            dp[i] = max(dp[i-1], dp[i-2] + nums[i])

        return dp[-1]

class Solution:
    def maxDepth(self, root: Optional[TreeNode]) -> int:
        if root is None:
            return 0
        depth = 0
        stack = [(root, 1)]
        while stack:
            node, current = stack.pop()
            depth = max(depth, current)
            if node.left is not None:
                stack.append((node.left, current + 1))
            if node.right is not None:
                stack.append((node.right, current + 1))
        return depth

class Solution:
    def isSymmetric(self, root: Optional[TreeNode]) -> bool:
        if root is None:
            return True
        stack = [(root.left, root.right)]
        while stack:
            left, right = stack.pop()
            if left is None or right is None:
                if left is not right:
                    return False
                continue
            if left.val != right.val:
                return False
            stack.append((left.left, right.right))
            stack.append((left.right, right.left))
        return True

class Solution:
    def mergeTrees(self, root1: Optional[TreeNode], root2: Optional[TreeNode]) -> Optional[TreeNode]:
        if root1 is None:
            return root2
        if root2 is None:
            return root1
        result = TreeNode(root1.val + root2.val)
        stack = [(result, root1, root2)]
        while stack:
            merged, first, second = stack.pop()
            for side in ('left', 'right'):
                left, right = getattr(first, side), getattr(second, side)
                if left is None or right is None:
                    setattr(merged, side, right if left is None else left)
                else:
                    child = TreeNode(left.val + right.val)
                    setattr(merged, side, child)
                    stack.append((child, left, right))
        return result

class Solution:
    def coinChange(self, coins: List[int], amount: int) -> int:
        # Bottom-up DP tabulating min coins for each amount up to target
        dp = [float('inf')] * (amount + 1)
        dp[0] = 0

        for coin in coins:
            for x in range(coin, amount + 1):
                dp[x] = min(dp[x], dp[x - coin] + 1)

        return dp[amount] if dp[amount] != float('inf') else -1

class Solution:
    def isSubtree(self, root: Optional[TreeNode], subRoot: Optional[TreeNode]) -> bool:
        def same(first, second):
            pairs = [(first, second)]
            while pairs:
                left, right = pairs.pop()
                if left is None or right is None:
                    if left is not right:
                        return False
                    continue
                if left.val != right.val:
                    return False
                pairs.append((left.left, right.left))
                pairs.append((left.right, right.right))
            return True

        if subRoot is None:
            return True
        stack = [root] if root is not None else []
        while stack:
            node = stack.pop()
            if node.val == subRoot.val and same(node, subRoot):
                return True
            if node.left is not None:
                stack.append(node.left)
            if node.right is not None:
                stack.append(node.right)
        return False

class Solution:
    def wordBreak(self, s: str, wordDict: List[str]) -> bool:
        # DP approach checking feasibility for prefixes
        words = set(wordDict)
        dp = [False] * (len(s) + 1)
        dp[0] = True

        for i in range(1, len(s) + 1):
            for j in range(i):
                if dp[j] and s[j:i] in words:
                    dp[i] = True
                    break
        return dp[-1]

class Solution:
    def numDecodings(self, s: str) -> int:
        # Linear dynamic programming keeping track of decodings
        if not s or s[0] == '0':
            return 0
        n = len(s)
        dp = [0] * (n + 1)
        dp[0] = 1
        dp[1] = 1

        for i in range(2, n + 1):
            if s[i-1] != '0':
                dp[i] += dp[i-1]
            two_digit = int(s[i-2:i])
            if 10 <= two_digit <= 26:
                dp[i] += dp[i-2]
        return dp[n]

from collections import deque


class Solution:
    def levelOrder(self, root: Optional[TreeNode]) -> List[List[int]]:
        if root is None:
            return []
        result = []
        queue = deque([root])
        while queue:
            level = []
            for _ in range(len(queue)):
                node = queue.popleft()
                level.append(node.val)
                if node.left is not None:
                    queue.append(node.left)
                if node.right is not None:
                    queue.append(node.right)
            result.append(level)
        return result

class Solution:
    def uniquePaths(self, m: int, n: int) -> int:
        # DP table approach to achieve O(m * n) time and space
        dp = [[1] * n for _ in range(m)]
        for i in range(1, m):
            for j in range(1, n):
                dp[i][j] = dp[i-1][j] + dp[i][j-1]
        return dp[m-1][n-1]

class Solution:
    def minPathSum(self, grid: List[List[int]]) -> int:
        # 2D Dynamic Programming to find global minimum path sum
        m, n = len(grid), len(grid[0])
        dp = [[0] * n for _ in range(m)]
        dp[0][0] = grid[0][0]

        for j in range(1, n):
            dp[0][j] = dp[0][j-1] + grid[0][j]
        for i in range(1, m):
            dp[i][0] = dp[i-1][0] + grid[i][0]

        for i in range(1, m):
            for j in range(1, n):
                dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + grid[i][j]

        return dp[m-1][n-1]

class Solution:
    def isSameTree(self, p: Optional[TreeNode], q: Optional[TreeNode]) -> bool:
        stack = [(p, q)]
        while stack:
            left, right = stack.pop()
            if left is None or right is None:
                if left is not right:
                    return False
                continue
            if left.val != right.val:
                return False
            stack.append((left.left, right.left))
            stack.append((left.right, right.right))
        return True

class Solution:
    def hasPathSum(self, root: Optional[TreeNode], targetSum: int) -> bool:
        stack = [(root, root.val)] if root is not None else []
        while stack:
            node, total = stack.pop()
            if node.left is None and node.right is None and total == targetSum:
                return True
            if node.left is not None:
                stack.append((node.left, total + node.left.val))
            if node.right is not None:
                stack.append((node.right, total + node.right.val))
        return False

class Solution:
    def maxProfit(self, prices: List[int]) -> int:
        lowest, best = prices[0], 0
        for price in prices:
            lowest = min(lowest, price)
            best = max(best, price - lowest)
        return best

class Solution:
    def search(self, nums: List[int], target: int) -> int:
        left, right = 0, len(nums) - 1
        while left <= right:
            middle = (left + right) // 2
            if nums[middle] == target:
                return middle
            if nums[middle] < target:
                left = middle + 1
            else:
                right = middle - 1
        return -1

